CREATE TABLE acquisition_sources(id TEXT PRIMARY KEY, sport TEXT NOT NULL, region TEXT NOT NULL, config_json TEXT NOT NULL, last_attempt TEXT, last_success TEXT, retrieval_status TEXT NOT NULL, failure_reason TEXT, next_due TEXT, cache_json TEXT);
CREATE TABLE acquisition_runs(id TEXT PRIMARY KEY, job TEXT NOT NULL, mode TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, report_json TEXT NOT NULL);
CREATE UNIQUE INDEX acquisition_single_active_job ON acquisition_runs(job) WHERE status='running';
CREATE TABLE acquisition_observations(id INTEGER PRIMARY KEY, run_id TEXT NOT NULL REFERENCES acquisition_runs(id), source_id TEXT NOT NULL REFERENCES acquisition_sources(id), at TEXT NOT NULL, status TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE acquisition_records(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES acquisition_sources(id), native_id TEXT NOT NULL, current_version INTEGER NOT NULL, approved_version INTEGER, lifecycle TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE acquisition_record_versions(record_id TEXT NOT NULL REFERENCES acquisition_records(id), version INTEGER NOT NULL, run_id TEXT NOT NULL REFERENCES acquisition_runs(id), observed_at TEXT NOT NULL, semantic_hash TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(record_id,version));
CREATE TABLE acquisition_reviews(id INTEGER PRIMARY KEY, record_id TEXT NOT NULL REFERENCES acquisition_records(id), version INTEGER NOT NULL, at TEXT NOT NULL, reviewer TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, evidence_url TEXT NOT NULL);
